
public class Ejercicio01 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//DECLARACION DE VARIABLES
		int num; 
		String nombre;

		//INICIALIZACION DE VARIABLES
		num=25;
		nombre="DAM1";

		//MOSTRAR VALORES
		//El valor dle numero es: 25.

		System.out.println("El valor del número es: "+num+".");
		//Estamos en clase de DAM1.
		System.out.println("Esyamos en clase de: "+nombre+".");

		//MODIFICAR EL VALOR DEL NUMERO: SUMARLE 35
		num=num+35; //num=60
		num+=5;     //num=65
		
		num=num+1;	//num=66
		num++;		//num=67
		num--;		//num=66
		System.out.println(num+1); //num=66 pero se le hace la suma 
		
		System.out.println("El valor del numero es:" +num);
		
		//VOLVER A MOSTRAR EL VALOR DEL NUMERO 
		
		
		
		System.out.println("Hola Mundo!!!");
	}

}
